export type TourId =
  "rio-express" | "tailor-made" | "rio-nature" | "helicopter" | "carnaval" | "boat";

export type TourMeta = {
  id: TourId;
  /** Base name of the optimized image in src/assets/optimized (see ResponsiveImage) */
  imageName: string;
  highlight?: "mostLoved" | "premium";
  /** Public path of the 1200x630 social image generated by `npm run images` */
  ogImage: string;
  /** Starting price in USD per group. Leave undefined until confirmed: schema.org offers only appear when set. */
  priceFrom?: number;
  /** Ordered list of attractions, used as the itinerary in structured data. */
  attractions: string[];
};

export const tours: TourMeta[] = [
  {
    id: "rio-express",
    ogImage: "/og/rio-express.jpg",
    imageName: "tour-christ",
    highlight: "mostLoved",
    attractions: ["Christ the Redeemer", "Sugarloaf Mountain", "Selarón Steps", "Copacabana Beach"],
  },
  {
    id: "tailor-made",
    ogImage: "/og/tailor-made.jpg",
    imageName: "tour-sugarloaf",
    attractions: ["Rio de Janeiro"],
  },
  {
    id: "rio-nature",
    ogImage: "/og/rio-nature.jpg",
    imageName: "tour-nature",
    attractions: ["Tijuca Forest", "Rio de Janeiro Botanical Garden"],
  },
  {
    id: "helicopter",
    ogImage: "/og/helicopter.jpg",
    imageName: "tour-helicopter",
    highlight: "premium",
    attractions: ["Christ the Redeemer", "Sugarloaf Mountain", "Copacabana Beach", "Ipanema Beach"],
  },
  {
    id: "carnaval",
    ogImage: "/og/carnaval.jpg",
    imageName: "tour-carnaval",
    attractions: ["Sambadrome", "Maracanã Stadium"],
  },
  {
    id: "boat",
    ogImage: "/og/boat.jpg",
    imageName: "tour-boat",
    attractions: ["Sugarloaf Mountain", "Guanabara Bay", "Niterói"],
  },
];

export function getTour(id: string): TourMeta | undefined {
  return tours.find((tour) => tour.id === id);
}
